// Conceptual class mimicking std::locale structure

class LocaleContainer {
public:
    // Template member function specializing behavior
    // based on the compile-time type argument (Facet).
    template <typename Facet>
    bool has_facet() const {
        // Body uses Facet type information (e.g., typeid or traits)
        return sizeof(Facet) > 0;
    }
};

// Example usage demonstrating template specialization
struct NumpunctFacet {};
struct CollateFacet {};

LocaleContainer current_locale;
bool num_found = current_locale.has_facet<NumpunctFacet>();
bool coll_found = current_locale.has_facet<CollateFacet>();
